VALUES (13562, 'tt0028010', NULL, 'My Man Godfrey', 'My Man Godfrey', 'movie', 1936, 'https://image.tmdb.org/t/p/w500/wtfOW7fIxBZWY78rvUoPpWhMSiR.jpg', 'https://image.tmdb.org/t/p/original/96cNUk1Uj8fQcmbOTnpBauUdqzC.jpg', 'Fifth Avenue socialite Irene Bullock needs a "forgotten man" to win a scavenger hunt, and no one is more forgotten than Godfrey Park, who resides in a dump by the East River. Irene hires Godfrey as a servant for her riotously unhinged family, to the chagrin of her spoiled sister, Cornelia, who tries her best to get Godfrey fired. As Irene falls for her new butler, Godfrey turns the tables and teaches the frivolous Bullocks a lesson or two.', NULL, NULL, 4.4391, 7.585, 0, 10.69, '2026-10-19 04:56:39', '2026-10-19 04:56:39')
