VALUES (3080, 'tt0027125', NULL, 'Top Hat', 'Top Hat', 'movie', 1935, 'https://image.tmdb.org/t/p/w500/qoPBiN6PBs2NsP7BNOJGCnmwruG.jpg', 'https://image.tmdb.org/t/p/original/9riMLH4EOw6PZzeCDnPlIGSyiEu.jpg', 'Showman Jerry Travers is working for producer Horace Hardwick in London. Jerry demonstrates his new dance steps late one night in Horace''s hotel room, much to the annoyance of sleeping Dale Tremont below. She goes upstairs to complain and the two are immediately attracted to each other. Complications arise when Dale mistakes Jerry for Horace.', NULL, NULL, 5.1227, 7.2, 0, 10.51, '2026-10-19 04:56:39', '2026-10-19 04:56:39')
