VALUES (15271, 'tt0325123', NULL, 'Bright Young Things', 'Bright Young Things', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/m7ik01FJKBSEoy0L0PKz7eEf9kI.jpg', 'https://image.tmdb.org/t/p/original/gP3fRkvy0ABEorenM76QHKefBOa.jpg', 'During the 1930s in England, a group of young socialites dominate the national gossip with extravagant and outlandish antics. Among the group is the aspiring novelist Adam Fenwick-Symes, who is attempting to raise enough money to marry fellow member Nina Blount. However, after customs officials confiscate his first manuscript, Fenwick-Symes must recover from the financial setback and figure out new ways to earn money for a wedding.', NULL, NULL, 3.2968, 6.3, 0, 10.52, '2026-10-19 04:56:39', '2026-10-19 04:56:39')
