VALUES (NULL, NULL, 136558, 'Magic: The Gathering', 'Magic: The Gathering', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2erv.jpg', NULL, 'Magic: The Gathering is a Dreamcast game published and released by Sega in June 2001, though in Japan only. It takes place in the town of Magic Heart, the surrounding areas of Murg, Camat Island, Lydar Forest, Yeluk, Tornell, and The Balance Tower. It includes cards from 6th edition, Alliances, and Tempest. The game included 10 cards unique to it, generally utilizing random mechanics that would be difficult to implement in real-life card play.', 'https://www.igdb.com/games/magic-the-gathering--1', '["Dreamcast"]', NULL, NULL, 0, 11.05, '2026-10-19 04:56:39', '2026-10-19 04:56:39')
