VALUES (46212, 'tt0175581', NULL, 'Dragon''s Return', 'Drak sa vracia', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/9DBYGjn7tHSUDnSyD0V2duzS9AE.jpg', 'https://image.tmdb.org/t/p/original/t17cJDxpoJHUt7VhDwn9ljeNin4.jpg', 'This is a ballad about love, hate, and a search for a way out of loneliness. It is a dramatic story about the strange potter, Martin Leaps, nicknamed Dragon, who is suspected by the villagers as the cause of natural disasters. He lost his wife, his home, and his freedom due to false accusations. After years he returns to his native village. Putting his own life to risk, he saves a herd of cows from a forest fire in the hills. But not even this heroic deed helps him to win back the friendship of the locals.', NULL, NULL, 1.3628, 7.3, 0, 10.51, '2026-10-19 04:56:39', '2026-10-19 04:56:39')
