VALUES (27361, 'tt0072709', NULL, 'Black Moon', 'Black Moon', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/tsbauHYC5E7YK7UeMl3FM4U9xhK.jpg', 'https://image.tmdb.org/t/p/original/luRLohOI29820ZKUgPg84wquMqi.jpg', 'There is a global gender war between men and women. A teenage girl tries to escape this reality and arrives at a hidden place where a strange unicorn lives with a family: sister, brother, many children and an old, bedridden woman who stays in contact with the world through her radio.', NULL, NULL, 1.4607, 5.963, 0, 1.05233333333333334e+01, '2026-07-15 12:01:52', '2026-10-19 04:56:39')
