VALUES (4087, 'tt0106179', NULL, 'The X-Files', 'The X-Files', 'tv', 1993, 'https://image.tmdb.org/t/p/w500/rcBx0p8h51LHceyhquYMxbspJQu.jpg', 'https://image.tmdb.org/t/p/original/w00lfexrsOeR25dO4hsWhbcUnmD.jpg', 'The exploits of FBI Special Agents Fox Mulder and Dana Scully who investigate X-Files: marginalized, unsolved cases involving paranormal phenomena. Mulder believes in the existence of aliens and the paranormal while Scully, a skeptic, is assigned to make scientific analyses of Mulder''s discoveries that debunk Mulder''s work and thus return him to mainstream cases.', NULL, NULL, 74.6017, 8.4, 0, 6.32122033898305062e+01, '2026-07-15 12:01:52', '2026-10-19 04:56:39')
