VALUES (347031, 'tt4034354', NULL, 'Swiss Army Man', 'Swiss Army Man', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/xE2QfqvAGI8n8ckIiy9FzS9XF94.jpg', 'https://image.tmdb.org/t/p/original/xo6Sedrdj4DVnh4ZEzDM4D0QQYU.jpg', 'Alone on a tiny deserted island, Hank has given up all hope of ever making it home again. But one day everything changes when a dead body washes ashore, and he soon realizes it may be his last opportunity to escape certain death. Armed with his new “friend” and an unusual bag of tricks, the duo go on an epic adventure to bring Hank back to the woman of his dreams.', NULL, NULL, 3.6237, 6.917, 0, 2.98974074074074067e+01, '2026-07-15 12:01:52', '2026-10-19 04:56:39')
