VALUES (70796, 'tt5788792', NULL, 'The Marvelous Mrs. Maisel', 'The Marvelous Mrs. Maisel', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/zS7fQiOZiKCVH2vlYSiIsFWW8hh.jpg', 'https://image.tmdb.org/t/p/original/vQ77kC1amsZECKIxkUIsMJCtBVp.jpg', 'It’s 1958 Manhattan and Miriam “Midge” Maisel has everything she’s ever wanted - the perfect husband, kids, and Upper West Side apartment. But when her life suddenly takes a turn and Midge must start over, she discovers a previously unknown talent - one that will take her all the way from the comedy clubs of Greenwich Village to a spot on Johnny Carson’s couch.', NULL, NULL, 29.146, 8.065, 0, 1.30285714285714284e+01, '2026-07-15 12:01:52', '2026-10-19 04:56:39')
