VALUES (36557, 'tt0381061', NULL, 'Casino Royale', 'Casino Royale', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg', 'https://image.tmdb.org/t/p/original/klJMCIblHLFwCuGjKz7tyOpekIC.jpg', 'Le Chiffre, a banker to the world''s terrorists, is scheduled to participate in a high-stakes poker game in Montenegro, where he intends to use his winnings to establish his financial grip on the terrorist market. M sends Bond—on his maiden mission as a 00 Agent—to attend this game and prevent Le Chiffre from winning. With the help of Vesper Lynd and Felix Leiter, Bond enters the most important poker game in his already dangerous career.', NULL, NULL, 13.7861, 7.575, 0, 1.56761538461538449e+01, '2026-07-30 18:28:39', '2026-10-19 04:56:39')
