VALUES (9687, 'tt0118414', NULL, 'The Odyssey', 'The Odyssey', 'tv', 1997, 'https://image.tmdb.org/t/p/w500/wCiQ7XySqnz9X1REtDNZRGLfhpe.jpg', 'https://image.tmdb.org/t/p/original/jmCegdxo0woQ3GpI3IuR7XxSMWN.jpg', 'Warrior Odysseus leaves his idyllic life in the kingdom of Ithaca to fight in the Trojan War. Following victory, he now must endure a lengthy, decade-long return journey, and with all his wits, overcome deadly monsters, powerful forces of nature, seductive enchantresses, and even journey into the bowels of the Underworld.', NULL, NULL, 33.365, 7.2, 0, 1.77655555555555544e+01, '2026-07-31 03:33:23', '2026-10-19 04:56:39')
