VALUES (18919, 'tt0109781', NULL, 'Faust', 'Lekce Faust', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/pyCHHLEdRJPx0BD22n9Cs7B78Wp.jpg', 'https://image.tmdb.org/t/p/original/qiGF1b2vH38WRWQooLp3q9LS7m2.jpg', 'A very free adaptation of Marlowe''s "Doctor Faustus", Goethe''s "Faust" and various other treatments of the old legend of the man who sold his soul to the devil. A nondescript man is lured by a strange map into a sinister puppet theatre, where he finds himself immersed in an indescribably weird version of the play, blending live actors, clay animation and giant puppets.', NULL, NULL, 1.4537, 7.4, 0, 1.34063636363636362e+01, '2026-08-03 14:31:56', '2026-10-19 04:56:39')
