VALUES (11676, 'tt0119807', NULL, 'Nothing to Lose', 'Nothing to Lose', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/umbzQyRMeB1oHTKiymTlH591xNB.jpg', 'https://image.tmdb.org/t/p/original/y7fsDAazaQudZHMrTTegPjWdFT.jpg', 'Advertising executive Nick Beame learns that his wife is sleeping with his employer. In a state of despair, he encounters a bumbling thief whose attempted carjacking goes awry when Nick takes him on an involuntary joyride. Soon the betrayed businessman and the incompetent crook strike up a partnership and develop a robbery-revenge scheme. But it turns out that some other criminals in the area don''t appreciate the competition.', NULL, NULL, 7.1418, 6.607, 0, 12.51, '2026-08-19 01:49:52', '2026-10-19 04:56:39')
