VALUES (432527, 'tt5935704', NULL, 'Padmaavat', 'पद्मावत', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/5kk71s8Vmvt8XQOojevhTA5QcB0.jpg', 'https://image.tmdb.org/t/p/original/50reJgWrWTXK3fvGh8idw71gxAO.jpg', 'Rajputana, India, 13th century. The tyrannical usurper Alauddin Khilji, sultan of Delhi, becomes obsessed with Queen Padmavati, wife of King Ratan Singh of Mewar, and goes to great lengths to satisfy his greed for her.', NULL, NULL, 2.9294, 6.916, 0, 1.21866666666666656e+01, '2026-10-16 22:59:46', '2026-10-19 04:56:39')
